const originalText=new WeakMap();function localize(root=document){if(!root)return;const w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let n;while((n=w.nextNode())){if(!originalText.has(n))originalText.set(n,n.nodeValue);let raw=originalText.get(n),trim=raw.trim(),replacement=currentLang==='en'?EN[trim]:null,next=replacement?raw.replace(trim,replacement):raw;if(n.nodeValue!==next)n.nodeValue=next}root.querySelectorAll?.('[placeholder],[aria-label]').forEach(el=>{for(const a of ['placeholder','aria-label']){const key='rafOriginal'+a,raw=el.dataset[key]||el.getAttribute(a);if(!el.dataset[key])el.dataset[key]=raw;const next=currentLang==='en'?(EN[raw]||raw):raw;if(el.getAttribute(a)!==next)el.setAttribute(a,next)}})}
const catName=k=>{const name=(CATEGORIES.find(x=>x[0]===k)||[])[2]||k;return currentLang==='en'?({Film:'Film',Dizi:'Series',Anime:'Anime',Donghua:'Donghua',Manga:'Manga',Novel:'Light novel',Kitap:'Book'}[name]||name):name};
function nav(){document.querySelector('#category-nav').innerHTML=CATEGORIES.map(([k,icon,label])=>`<button class="nav-item ${view===k?'active':''}" data-view="${k}"><span class="nav-icon">${icon}</span><span>${label}</span><span class="nav-count">${k==='all'?db.items.length:db.items.filter(i=>i.category===k).length}</span></button>`).join('');document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));document.querySelector('#favorite-count').textContent=db.items.filter(i=>i.favorite).length;}
function card(i){return `<article class="media-card" data-edit="${esc(i.id)}"><div class="poster p${i.color||1}"><span class="poster-mark">${i.favorite?'♥ · ':''}${catName(i.category).toUpperCase()}</span><span class="poster-title">${esc(i.title)}</span></div><div class="card-body"><span class="card-type">${catName(i.category)} · ${esc(i.creator.split('·')[0].trim())}</span><h3>${esc(i.title)}</h3><div class="card-meta">${esc(i.progress||i.creator)}</div><div class="card-bottom"><span class="stars">${i.rating?'★'.repeat(i.rating)+'<span style="color:#59645d">'+'★'.repeat(5-i.rating)+'</span>':'<span style="color:#66736b">Değerlendirilmedi</span>'}</span><span class="card-status">${esc(i.status)}</span></div></div></article>`}
function home(){const shown=db.items.filter(i=>(view==='all'||i.category===view)&&(!query||(i.title+' '+i.creator+' '+i.note).toLocaleLowerCase('tr').includes(query.toLocaleLowerCase('tr'))));document.querySelector('#current-crumb').textContent=view==='all'?'Genel bakış':catName(view);return `<section class="hero"><div><span class="eyebrow">PAZAR · 25 EKİM 2026</span><h1>Hikâyelerden bir <em>iz</em> kalır.</h1><p>İzlediğin, okuduğun, dönüp dönüp düşündüğün her şey için kendine ait bir raf.</p></div><div class="hero-aside"><small>RAFINDaki</small><strong>${db.items.length.toString().padStart(2,'0')}</strong><span>hikâye ve yolculuk</span></div></section><section class="hero-feature"><div class="feature-copy"><span class="eyebrow">KÜÇÜK BİR BAŞLANGIÇ</span><h2>Bir sonraki hikâyen için yer aç.</h2><p>İzlediklerini ve okuduklarını tek bir sakin köşede tut.</p><button class="primary-btn" data-action="add">＋ Yeni kayıt ekle</button></div><div class="feature-metric"><strong>${db.items.filter(i=>i.rating>=4).length}</strong><span>GÜZEL HATIRA</span></div></section><div class="section-heading"><div><h2>${view==='all'?'Rafından seçmeler':catName(view)+' rafı'}</h2><p>Son eklediklerin ve kaldığın yer.</p></div><button class="subtle-btn" data-view="all">Tüm arşiv →</button></div><div class="filter-row">${['Hepsi','İzleniyor','Okunuyor','Devam ediyor','Tamamlandı','İzlenecek','Okunacak'].map(s=>`<button class="filter-chip ${statusFilter===s?'active':''}" data-status="${s}">${s}</button>`).join('')}</div><div class="shelf-grid">${shown.filter(i=>statusFilter==='Hepsi'||i.status===statusFilter).length?shown.filter(i=>statusFilter==='Hepsi'||i.status===statusFilter).map(card).join(''):'<div class="empty-state"><b>Bu rafta henüz bir hikâye yok.</b>İlk kaydını ekleyerek başlayabilirsin.</div>'}</div>`}
function special(){if(view==='forum'){document.querySelector('#current-crumb').textContent='Forum sohbetleri';return forumPage()}document.querySelector('#current-crumb').textContent=view==='favorites'?'Favoriler':'İz / istatistik';if(view==='favorites'){let list=db.items.filter(i=>i.favorite);return `<span class="eyebrow">SENİN ALANIN</span><h1 class="page-title">Favoriler</h1><p class="page-intro">Dönüp yeniden uğramak istediğin hikâyeler.</p><div class="shelf-grid">${list.length?list.map(card).join(''):'<div class="empty-state"><b>Henüz favorin yok.</b>Bir kaydı açıp kalp simgesini işaretleyebilirsin.</div>'}</div>`}let complete=db.items.filter(i=>i.status==='Tamamlandı').length, rated=db.items.filter(i=>i.rating).length, avg=rated?(db.items.reduce((a,i)=>a+i.rating,0)/rated).toFixed(1):'—';return `<span class="eyebrow">SENİN ALANIN</span><h1 class="page-title">İz / istatistik</h1><p class="page-intro">Arşivin sana dair küçük bir harita.</p><div class="stat-grid"><div class="stat-card"><span>TOPLAM HİKÂYE</span><strong>${db.items.length}</strong><small>farklı yolculuk</small></div><div class="stat-card"><span>TAMAMLANAN</span><strong>${complete}</strong><small>sonuna kadar eşlik ettin</small></div><div class="stat-card"><span>ORTALAMA PUAN</span><strong>${avg}${avg==='—'?'':' / 5'}</strong><small>${rated} değerlendirme</small></div></div><div class="section-heading"><div><h2>Türlere göre</h2><p>Rafının dağılımı</p></div></div><div class="shelf-grid">${CATEGORIES.slice(1).map(([k,ic,n])=>`<button class="stat-card" data-view="${k}" style="text-align:left;border:1px solid #26302e;color:inherit"><span>${ic} ${n.toLocaleUpperCase('tr')}</span><strong>${db.items.filter(i=>i.category===k).length}</strong><small>kayıt · koleksiyona git →</small></button>`).join('')}</div>`}
function render(){nav();document.querySelector('#page-content').innerHTML=(view==='favorites'||view==='stats'||view==='forum')?special():home();localize(document.querySelector('.app-shell'));document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;statusFilter='Hepsi';render()});document.querySelectorAll('[data-status]').forEach(b=>b.onclick=()=>{statusFilter=b.dataset.status;render()});document.querySelectorAll('[data-action="add"]').forEach(b=>b.onclick=()=>openEntry());document.querySelectorAll('[data-edit]').forEach(c=>c.onclick=()=>openEntry(db.items.find(x=>x.id===c.dataset.edit)));document.querySelectorAll('[data-legal]').forEach(b=>b.onclick=()=>openLegal(b.dataset.legal));if(view==='forum')wireForum();}
function forumPage(){if(!desktop)return `<span class="eyebrow">İSTEĞE BAĞLI · ÇEVRİMİÇİ</span><h1 class="page-title">Forum sohbetleri</h1><div class="empty-state"><b>Forum bağlantısı masaüstü sürümünde kullanılabilir.</b>Bu önizleme çevrimdışı ve tek kullanıcı içindir.</div>`;if(!db.user)return `<span class="eyebrow">İSTEĞE BAĞLI · ÇEVRİMİÇİ</span><h1 class="page-title">Forum sohbetleri</h1><div class="empty-state"><b>Önce yerel hesabına giriş yap.</b>Forum bağlantı anahtarı cihazındaki hesapla şifrelenir.</div>`;return `<span class="eyebrow">İSTEĞE BAĞLI · ÇEVRİMİÇİ</span><h1 class="page-title">Forum sohbetleri</h1><p class="page-intro">Mevcut Discourse hesabını bağla; özel mesaj konularını ve odalarını bu panelden yönet.</p><div class="account-card"><b>Gizlilik notu</b><br>Bağlantı açıldığında forum sunucusuna kimliğin ve gönderdiğin mesajlar gider. Sohbetleri forum sağlayıcısı saklar ve oda katılımcıları görebilir. Bu özellik kapalıyken RAF çevrimdışı kalır.</div><div id="forum-content" class="empty-state">Forum bağlantısı denetleniyor…</div>`}
async function wireForum(){if(!desktop||!db.user)return;let host=document.querySelector('#forum-content');if(!host)return;try{let status=await window.rafDesktop.discourseStatus();if(!status){host.className='';host.innerHTML=`<div class="hero-feature" style="margin-top:4px"><div class="feature-copy"><span class="eyebrow">DISCOURSE · KULLANICI ONAYI</span><h2>Mevcut forum hesabını bağla.</h2><p>RAF, giriş bilgini istemez. Forum, RAF uygulaması için sınırlı erişim anahtarı üretmeni ve onaylamanı ister.</p><button class="primary-btn" id="connect-discourse">Forum hesabını bağla</button></div></div><p class="page-intro" style="margin-top:16px">Bağlantı, mesajları okuma ve gönderme izni ister. İzni forum hesabının uygulamalar sayfasından dilediğin zaman kaldırabilirsin.</p>`;document.querySelector('#connect-discourse').onclick=connectDiscourse;return}host.className='';host.innerHTML=`<div class="section-heading"><div><h2>${esc(status.origin)}</h2><p>@${esc(status.username)} · ${currentLang==='en'?'connected Discourse account':'bağlı Discourse hesabı'}</p></div><div><button class="secondary-btn" id="refresh-rooms">Yenile</button> <button class="secondary-btn" id="new-room">＋ Özel oda</button> <button class="danger-btn" id="disconnect-forum">Bağlantıyı kes</button></div></div><div id="room-list" class="shelf-grid"><div class="empty-state">Sohbet odaları yükleniyor…</div></div>`;document.querySelector('#refresh-rooms').onclick=loadRooms;document.querySelector('#new-room').onclick=openNewRoom;document.querySelector('#disconnect-forum').onclick=async()=>{if(!confirm(tx('Forum bağlantısını kesmek ve forum API anahtarını iptal etmeyi denemek istiyor musun?')))return;try{await window.rafDesktop.discourseDisconnect();toast('Forum bağlantısı kesildi.');wireForum()}catch(e){toast(e.message||'Forum bağlantısı kesilemedi.')}};await loadRooms()}catch(e){host.className='empty-state';host.innerHTML=`<b>Forum bağlantısı kullanılamıyor.</b>${esc(tx(e.message))} <button class="text-btn" id="forum-retry">Yeniden dene</button>`;document.querySelector('#forum-retry').onclick=wireForum}}
async function connectDiscourse(){document.querySelector('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="entry-modal" style="max-width:490px"><div class="modal-head"><div><span class="eyebrow">DISCOURSE BAĞLANTISI</span><h2 style="margin-top:8px">Forum hesabını bağla</h2><p>Forum adresini yaz; onayı o forumun kendi sayfasında vereceksin.</p></div><button class="close-btn" data-close>×</button></div><form id="forum-connect-form"><div class="field"><label>FORUM ADRESİ · HTTPS</label><input name="origin" type="url" required placeholder="https://forum.example.org"/></div><div class="account-card" style="margin-top:14px">RAF, forum parolanı veya API anahtarını istemez. Forumun resmi kullanıcı onay ekranı açılır. Onaylanan anahtar yalnızca yerel şifreli hesap klasöründe saklanır.</div><div class="form-footer"><span id="forum-connect-error" class="form-note"></span><button type="submit" class="primary-btn">Forumda onayla…</button></div></form></section></div>`;document.querySelectorAll('[data-close]').forEach(b=>b.onclick=closeModal);document.querySelector('#forum-connect-form').onsubmit=async e=>{e.preventDefault();let button=e.target.querySelector('button[type=submit]');button.disabled=true;button.textContent='Forum yanıtı bekleniyor…';try{await window.rafDesktop.discourseConnect({origin:new FormData(e.target).get('origin')});closeModal();toast('Discourse hesabı bağlandı.');wireForum()}catch(err){document.querySelector('#forum-connect-error').textContent=tx(err.message)||'Bağlantı başarısız.';button.disabled=false;button.textContent='Yeniden dene'}}}
async function loadRooms(){let box=document.querySelector('#room-list');if(!box)return;box.innerHTML='<div class="empty-state">Sohbetler yenileniyor…</div>';try{let data=await window.rafDesktop.discourseRooms(),rooms=data?.topic_list?.topics||[];box.innerHTML=rooms.length?rooms.map(t=>`<button class="stat-card" data-room="${Number(t.id)}" style="text-align:left;border:1px solid #26302e;color:inherit"><span>ÖZEL SOHBET</span><strong style="font-size:20px">${esc(t.title||'Başlıksız oda')}</strong><small>${esc(t.last_poster_username||'')} · ${Number(t.posts_count)||0} mesaj</small></button>`).join(''):'<div class="empty-state"><b>Henüz özel sohbet yok.</b>Forum kullanıcı adlarıyla yeni bir oda başlat.</div>';document.querySelectorAll('[data-room]').forEach(b=>b.onclick=()=>openForumRoom(+b.dataset.room))}catch(e){box.innerHTML=`<div class="empty-state"><b>Forum sohbetleri alınamadı.</b>${esc(tx(e.message))}</div>`}}
function openNewRoom(){document.querySelector('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="entry-modal"><div class="modal-head"><div><h2>Özel oda oluştur</h2><p>Bu özel mesaj başlığı forum sunucusunda oluşturulur.</p></div><button class="close-btn" data-close>×</button></div><form id="new-room-form"><div class="form-grid"><div class="field full"><label>ODA ADI</label><input name="title" required maxlength="120"/></div><div class="field full"><label>FORUM KULLANICI ADLARI · VİRGÜLLE AYIR</label><input name="recipients" required placeholder="kullanici1, kullanici2"/></div><div class="field full"><label>İLK MESAJ</label><textarea name="body" required maxlength="20000"></textarea></div></div><p class="form-note">Gizli oda anlamı forumun özel mesaj özelliğidir; forum yöneticileri kendi hizmet koşulları uyarınca içeriğe erişebilir.</p><div class="form-footer"><span id="new-room-error" class="form-note"></span><button class="primary-btn">Odayı oluştur</button></div></form></section></div>`;document.querySelectorAll('[data-close]').forEach(b=>b.onclick=closeModal);document.querySelector('#new-room-form').onsubmit=async e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.target));try{await window.rafDesktop.discourseCreateRoom(d);closeModal();toast('Özel sohbet oluşturuldu.');await loadRooms()}catch(err){document.querySelector('#new-room-error').textContent=tx(err.message)||'Oda oluşturulamadı.'}}}
async function openForumRoom(id){let box=document.querySelector('#room-list');box.innerHTML='<div class="empty-state">Mesajlar yükleniyor…</div>';try{let topic=await window.rafDesktop.discourseRoom(id),posts=topic.post_stream?.posts||[];box.className='';box.innerHTML=`<div class="section-heading"><div><button class="text-btn" id="back-rooms">← Sohbetlere dön</button><h2>${esc(topic.title||'Özel sohbet')}</h2></div><button class="secondary-btn" id="refresh-room">Yenile</button></div><div class="room-messages">${posts.map(p=>`<article class="account-card"><b>${esc(p.username||'Forum üyesi')}</b><small style="float:right;color:#79887f">${esc((p.created_at||'').slice(0,16).replace('T',' '))}</small><p style="white-space:pre-wrap;margin:10px 0 0">${esc(p.raw||'')}</p></article>`).join('')}</div><form id="reply-form" style="margin-top:12px"><div class="field"><label>MESAJIN · FORUMDA GÖRÜNÜR</label><textarea name="body" required maxlength="20000" placeholder="Mesajını yaz…"></textarea></div><button class="primary-btn" style="margin-top:9px">Gönder</button><span id="reply-error" class="form-note" style="margin-left:10px"></span></form>`;document.querySelector('#back-rooms').onclick=loadRooms;document.querySelector('#refresh-room').onclick=()=>openForumRoom(id);document.querySelector('#reply-form').onsubmit=async e=>{e.preventDefault();try{await window.rafDesktop.discourseReply({topicId:id,body:new FormData(e.target).get('body')});await openForumRoom(id)}catch(err){document.querySelector('#reply-error').textContent=tx(err.message)||'Mesaj gönderilemedi.'}}}catch(e){box.innerHTML=`<div class="empty-state"><b>Sohbet açılamadı.</b>${esc(tx(e.message))}<button class="text-btn" onclick="loadRooms()">Geri dön</button></div>`}}
function toast(s){let t=document.querySelector('#toast');t.textContent=tx(s);t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2300)}
function openEntry(item){let editing=!!item;document.querySelector('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="entry-modal"><div class="modal-head"><div><h2>${editing?'Kaydı düzenle':'Rafına ekle'}</h2><p>Hikâyenin bilgilerini ve sende bıraktığı izi yaz.</p></div><button class="close-btn" data-close>×</button></div><form id="entry-form"><div class="form-grid"><div class="field full"><label>BAŞLIK *</label><input name="title" required maxlength="100" value="${esc(item?.title)}" placeholder="Örn. Spirited Away"/></div><div class="field"><label>TÜR</label><select name="category">${CATEGORIES.slice(1).map(([k,,n])=>`<option value="${k}" ${item?.category===k?'selected':''}>${n}</option>`).join('')}</select></div><div class="field"><label>DURUM</label><select name="status">${['İzlenecek','İzleniyor','Okunacak','Okunuyor','Devam ediyor','Tamamlandı','Bırakıldı'].map(s=>`<option value="${s}" ${item?.status===s?'selected':''}>${s}</option>`).join('')}</select></div><div class="field full"><label>YARATICI / YIL</label><input name="creator" value="${esc(item?.creator)}" placeholder="Yönetmen, yazar, yıl"/></div><div class="field"><label>KALDIĞIN YER</label><input name="progress" value="${esc(item?.progress)}" placeholder="12. bölüm / 80. sayfa"/></div><div class="field"><label>PUAN · 1–5</label><select name="rating"><option value="0">Henüz puan yok</option>${[1,2,3,4,5].map(n=>`<option value="${n}" ${item?.rating===n?'selected':''}>${'★'.repeat(n)} (${n})</option>`).join('')}</select></div><div class="field full"><label>NOTUN / DEĞERLENDİRMEN</label><textarea name="note" maxlength="1500" placeholder="Sende ne bıraktı? Spoiler varsa notuna ekle...">${esc(item?.note)}</textarea></div><div class="field full"><label><input style="width:auto;vertical-align:middle" type="checkbox" name="favorite" ${item?.favorite?'checked':''}/> Favorilerimde tut</label></div></div><div class="form-footer"><span class="form-note">Kayıtlar bu tarayıcıda saklanır. Buluta gönderilmez.</span><div class="modal-actions">${editing?'<button type="button" class="danger-btn" data-delete>Sil</button>':''}<button type="button" class="secondary-btn" data-close>Vazgeç</button><button class="primary-btn">${editing?'Kaydet':'Rafa ekle'}</button></div></div></form></section></div>`;document.querySelectorAll('[data-close]').forEach(b=>b.onclick=closeModal);document.querySelector('.modal-backdrop').onclick=e=>{if(e.target.classList.contains('modal-backdrop'))closeModal()};document.querySelector('#entry-form').onsubmit=e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.target));let obj={id:item?.id||crypto.randomUUID(),title:d.title.trim(),creator:d.creator.trim()||'Yaratıcı belirtilmedi',category:d.category,status:d.status,rating:+d.rating,progress:d.progress.trim()||'Sırada',note:d.note.trim(),favorite:!!e.target.favorite.checked,color:item?.color||1+Math.floor(Math.random()*8)};if(editing)db.items=db.items.map(x=>x.id===item.id?obj:x);else db.items.unshift(obj);save();closeModal();render();toast(editing?'Kaydın güncellendi.':'Rafına eklendi.')};let del=document.querySelector('[data-delete]');if(del)del.onclick=()=>{if(confirm(tx('Bu kaydı arşivinden silmek istiyor musun?'))){db.items=db.items.filter(x=>x.id!==item.id);save();closeModal();render();toast('Kayıt silindi.')}}}
let desktopLocked=false;
function closeModal(force=false){if(desktop&&desktopLocked&&!db.user&&!force)return;document.querySelector('#modal-root').innerHTML=''}
const legal={privacy:`<h3>Veri sorumlusu ve iletişim</h3><p>Veri sorumlusu: ....... · İletişim: <a href="mailto:b74433342@gmail.com">b74433342@gmail.com</a>. Bu uygulama açık kaynaklı, kişinin kendi bilgisayarında çalıştırdığı bir masaüstü programıdır. Her kullanıcı kendi cihazındaki kopyadan sorumludur.</p><h3>Çevrimdışı kullanım ve veri konumu</h3><p>Çevrimdışı mod varsayılan durumdur. RAF, başlıkları, değerlendirmeleri, notları, e-posta adresini ve hesap doğrulama kaydını bu cihazdaki uygulama veri klasöründe saklar. Kütüphane kayıtları film, dizi, anime, donghua, manga, novel ve kitap klasörlerine ayrılır. Uygulama bunları AES-256-GCM ile şifreler; parola doğrulaması scrypt ile yapılır. Uygulama bu bilgiler için bir RAF sunucusuna bağlanmaz, reklam veya analiz aracı kullanmaz. E-posta yalnızca cihaz içindeki yerel hesabın adı olarak kullanılır; doğrulama e-postası gönderilmez.</p><h3>İşleme amacı, yöntemi, hukuki sebep ve alıcılar</h3><p>Yerel kullanımda amaç, kullanıcının kendi medya arşivini oluşturmasıdır; kayıtlar kullanıcı arayüzünden girilir ve bu cihazın diskinde saklanır. RAF yazılım sağlayıcısına veya başka bir alıcıya aktarım yapılmaz. Uygulama sağlayıcısı bu yerel kayıtların veri sorumlusu değildir; kişisel veri ekleyen ve amaçlarını belirleyen kişi, üçüncü kişilere ait veri eklemeden önce kendi hukuki yükümlülüklerini değerlendirmelidir. Google bağlantısında Google, giriş isteğini alır; temel hesap profili RAF uygulamasına doğrudan bu cihaza döner. Discourse bağlantısında seçtiğin forum, kullanıcı kimliğini, özel mesaj odalarını ve gönderdiğin mesajları alıp saklar. Bu çevrimiçi hizmetlerin kendi veri sorumluları ve hukuki metinleri geçerlidir.</p><h3>İsteğe bağlı çevrimiçi bağlantılar</h3><p>Google oturumu ya da bir forum bağlantısı etkinleştirilirse, giriş ve ilgili sohbet işlemleri için gerekli bilgiler seçtiğin Google veya forum servisine iletilir. Bu servisler kendi gizlilik koşullarına göre veri işleyebilir. Çevrimiçi modlar varsayılan olarak kapalı olmalı ve ayrıca açılmalıdır. Çevrimdışı arşivini dış servise sen ayrıca dışa aktarmadıkça göndermez.</p><h3>Saklama, silme ve yedek</h3><p>Şifreli dosyalar sen silene kadar cihazında kalır; uygulamayı kaldırmak bu klasörü mutlaka silmez. Arşivi uygulama içinden temizleyebilir ya da uygulamanın veri klasörünü işletim sisteminden silebilirsin. Parolan unutulursa şifreli dosyaları kurtarmak mümkün değildir. Dışa aktarılan JSON yedeği şifrelenmemiştir; saklama yerini sen seçersin.</p><h3>Hakların</h3><p>KVKK kapsamındaki başvuru, bilgi alma, düzeltme ve silme taleplerin için veri sorumlusu iletişimine yazabilirsin. Çevrimdışı modda RAF işletmecisine arşiv verisi aktarılmadığından, cihazındaki kayıtları görme, düzeltme ve silme işlemleri doğrudan senin kontrolündedir. Bu metin anlaşılır bilgilendirme sunar; yaygınlaştırmadan önce veri sorumlusu kimliği, işleme şartı ve her çevrimiçi bağlayıcı için alıcılar netleştirilmelidir.</p><p>Resmî kaynaklar: <a target="_blank" rel="noreferrer" href="https://www.kvkk.gov.tr/Icerik/2033/Aydinlatma-Yukumlulugu-">KVKK Aydınlatma Yükümlülüğü</a> · <a target="_blank" rel="noreferrer" href="https://www.kvkk.gov.tr/Icerik/6765/AYDINLATMA-YUKUMLULUGUNUN-YERINE-GETIRILMESI-HAKKINDA-KAMUOYU-DUYURUSU">KVKK uygulama duyurusu</a> · <a target="_blank" rel="noreferrer" href="https://commission.europa.eu/law/law-topic/data-protection/information-business-and-organisations/principles-gdpr_en">Avrupa Komisyonu GDPR ilkeleri</a>.</p>`,terms:`<h3>Uygulamanın kullanımı</h3><p>RAF MIT lisansı ile yayımlanan kişisel arşiv yazılımıdır. Çevrimdışı kullanım için internet bağlantısı gerekmez. Uygulama senin cihazında çalışır; yedekleme ve işletim sistemi güvenliğini sağlamak senin sorumluluğundadır.</p><h3>Yerel hesap</h3><p>Hesap bilgileri yalnızca bu cihazda kullanılır ve başka cihazlara eşitlenmez. Parolanın unutulması halinde kurtarma hizmeti yoktur. Dışa aktarılan yedekler düz JSON olabilir; güvenli bir yerde sakla.</p><h3>Çevrimiçi bağlayıcılar</h3><p>Google veya Discourse gibi isteğe bağlı bağlantıları açtığında, bağlantı ve sohbet işlemlerinin dış servise veri göndermesini kabul etmiş olursun. Bu servislerin hesapları ve koşulları RAF'tan bağımsızdır. Bağlantıyı istediğin zaman kapatabilirsin.</p><h3>İçerik ve eser hakları</h3><p>Eklediğin not ve değerlendirmelerin hakları sende kalır; RAF'a içerik mülkiyeti devretmezsin. İzlenen/okunan eserlerin hakları kendi sahiplerine aittir. RAF eserlerin kopyalarını barındırmaz.</p><h3>Garanti</h3><p>Yazılım açık kaynaklıdır ve MIT lisansı uyarınca herhangi bir garanti verilmeksizin sunulur. Yedek almadan veri kaybına karşı koruma taahhüdü yoktur.</p>`,rights:`<h3>Kişisel verin üzerindeki hakların</h3><p>Eklediğin kayıtlar, puanlar ve notlar sana aittir. Uygulama bunları başka bir hizmete göndermez; yalnızca sen isteğe bağlı bir çevrimiçi bağlayıcıyı etkinleştirirsen o bağlayıcıyla ilgili veriler dış servise iletilir.</p><h3>Yazılım lisansı</h3><p>RAF'ın kaynak kodu MIT lisansı ile açık kaynak olarak paylaşılır. Lisansın izin ve koşulları <a target="_blank" rel="noreferrer" href="https://opensource.org/license/mit">MIT lisans metninde</a> yer alır. Yazılım lisansındaki izinler, RAF markası veya üçüncü taraf eserlerin haklarının devredildiği anlamına gelmez.</p><h3>Marka ve üçüncü taraf eserler</h3><p>RAF adı ve marka unsurları ilgili sahibine aittir; hakları saklıdır. Arşivlenen eser adlarının ve içeriklerinin hakları kendi hak sahiplerine aittir. İletişim: <a href="mailto:b74433342@gmail.com">b74433342@gmail.com</a></p>`};
const legalEN={
 privacy:`<h3>Data controller and contact</h3><p>Data controller: ....... · Contact: <a href="mailto:b74433342@gmail.com">b74433342@gmail.com</a>. RAF is an open-source desktop application that runs on each user’s own computer. The data controller’s identity must be completed by whoever distributes or configures this copy.</p><h3>Offline use and data location</h3><p>Offline use is the default. Your library entries, ratings, and notes are stored in this device’s RAFData folder, separated by media category. Library records are encrypted with AES-256-GCM. Local account metadata such as email, display name, password salt, and verifier is stored on this device but is not encrypted. Passwords are not stored in plain text; scrypt is used to derive and verify a key. RAF has no central account server, analytics, or advertising service. Local account email is not verified by email.</p><h3>Purpose, method, legal basis, and recipients</h3><p>In offline use, you enter records in the app and they remain on this computer; the RAF publisher does not receive them. Users are responsible for personal data they choose to enter about other people. When Google sign-in is enabled, Google receives the authentication request and the app receives basic profile information on this device. When Discourse is connected, the selected forum receives your account identity, private-room activity, and messages, and stores them under its own terms.</p><h3>Optional online connections</h3><p>Google sign-in and forum access are optional. Enabling either sends the information needed for that feature to the selected service. Those services have their own privacy policies and data controllers. The local library is not sent unless you separately export and share it.</p><h3>Retention, deletion, and backups</h3><p>Encrypted library files remain on this computer until you delete them. Uninstalling RAF may leave its data folder in place. You can clear the library in the app or remove the RAFData folder from the application data directory. Lost passwords cannot be recovered. Exported JSON backups are unencrypted; store them somewhere private.</p><h3>Your rights</h3><p>You can view, correct, export, and delete local records on this device. For requests about data processed by an optional external service, contact that service under its own privacy policy. Contact the distributor at the email above for questions about this copy. Complete the data-controller identity and obtain suitable legal review before distributing the app for organizational use or collecting data from others.</p><p>Official references: <a target="_blank" rel="noreferrer" href="https://www.kvkk.gov.tr/Icerik/2033/Aydinlatma-Yukumlulugu-">KVKK information notice obligation</a> · <a target="_blank" rel="noreferrer" href="https://www.kvkk.gov.tr/Icerik/6765/AYDINLATMA-YUKUMLULUGUNUN-YERINE-GETIRILMESI-HAKKINDA-KAMUOYU-DUYURUSU">KVKK public notice</a> · <a target="_blank" rel="noreferrer" href="https://commission.europa.eu/law/law-topic/data-protection/information-business-and-organisations/principles-gdpr_en">European Commission GDPR principles</a>.</p>`,
 terms:`<h3>Using RAF</h3><p>RAF is a personal media-library application distributed under the MIT License. The local library works offline. You are responsible for protecting your computer and keeping your own backups.</p><h3>Local account</h3><p>Local account data is specific to this device and is not synced. There is no password-recovery service. If you lose the local password, encrypted library records cannot be opened. Exported backups are unencrypted JSON unless you protect them yourself.</p><h3>Optional online services</h3><p>If you connect Google or a Discourse forum, the related sign-in and messaging data is sent to that service. Its account terms and privacy policy apply. You can disconnect an optional service from the app.</p><h3>Your content and third-party rights</h3><p>Your notes and reviews remain yours; you do not transfer ownership of them to RAF. Copyright in the media you track remains with its respective owners. RAF does not host copies of those works.</p><h3>Warranty</h3><p>The software is provided under the MIT License without warranty. RAF does not guarantee against data loss; keep regular backups.</p>`,
 rights:`<h3>Your personal data</h3><p>Your library entries, ratings, and notes are stored locally. You can view, correct, export, or delete them on this device. Optional Google or forum features send their related data to those services, which handle requests under their own policies.</p><h3>Software license</h3><p>RAF source code is open source under the MIT License. See the <a target="_blank" rel="noreferrer" href="https://opensource.org/license/mit">MIT License</a> for its permissions and conditions. The software license does not grant rights to the RAF name or third-party works.</p><h3>Trademarks and third-party works</h3><p>The RAF name and brand elements remain the property of their respective owner; all rights are reserved. Rights in the media titles and works you catalog belong to their respective owners. Contact: <a href="mailto:b74433342@gmail.com">b74433342@gmail.com</a>.</p>`
};
function openLegal(type){let title={privacy:'Gizlilik ve veri kullanımı',terms:'Kullanım koşulları',rights:'Haklar ve kullanım'}[type];if(currentLang==='en')title={privacy:'Privacy and data',terms:'Terms of use',rights:'Rights and use'}[type];let body=currentLang==='en'?legalEN[type]:legal[type];document.querySelector('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="entry-modal"><div class="modal-head"><div><span class="eyebrow">RAF · BİLGİ</span><h2 style="margin-top:8px">${title}</h2></div><button class="close-btn" data-close>×</button></div><div class="legal-copy">${body}</div><div class="form-footer"><span class="form-note">Son güncelleme: 25 Ekim 2026 · Prototip metni</span><button class="secondary-btn" data-close>Kapat</button></div></section></div>`;document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>closeModal(true))}
function desktopAccount(force=false){
 const u=db.user;
 desktopLocked=force&&!u;
 const xButton=force?'':'<button class="close-btn" data-close>×</button>';
 const top=`<div class="modal-backdrop"><section class="entry-modal" style="max-width:460px"><div class="modal-head"><div><span class="eyebrow">RAF · MASAÜSTÜ</span><h2 style="margin-top:8px">${u?'Yerel hesabın':'Cihazında oturum aç'}</h2><p>Hesap ve arşiv bu bilgisayardan çıkmaz.</p></div>${xButton}</div>`;
 const footer=`<div class="form-footer"><span class="form-note">Tamamen çevrimdışı kullanılabilir.</span><button class="text-btn" data-legal="privacy">Gizlilik</button></div></section></div>`;
 if(u){document.querySelector('#modal-root').innerHTML=top+`<div class="account-card"><b>${esc(u.name||'Kullanıcı')}</b><br>${esc(u.email)}<br><span style="color:#82b38d">● Yerel oturum açık · AES-256-GCM ile şifreli arşiv</span></div><div class="field full" style="margin:15px 0"><label>ARŞİV VERİSİ</label><p class="form-note">Konular ayrı klasörlerde tutulur. Hesap parolanı unutursan şifreli arşivi açmak mümkün olmaz; düzenli yedek al.</p></div><div style="display:flex;gap:8px;flex-wrap:wrap"><button class="secondary-btn" id="export-btn">Dışa aktar…</button><button class="secondary-btn" id="import-btn">Yedek içe aktar…</button><button class="secondary-btn" id="logout-btn">Oturumu kilitle</button><button class="danger-btn" id="clear-btn">Arşivi temizle</button></div>`+footer;
   const googlePanel=document.createElement('div');googlePanel.className='account-card';googlePanel.innerHTML=`<b>Google bağlantısı · isteğe bağlı</b><br>${u.googleLinked?'Google hesabı bu yerel hesaba bağlı.':'İstersen Google hesabını bu RAF profiline bağla; e-posta eşitlemesi yapılmaz.'}<div class="field" style="margin-top:10px"><label>GOOGLE DESKTOP CLIENT ID</label><input id="google-client-id" placeholder="....apps.googleusercontent.com"/></div><button id="google-link" class="secondary-btn" style="margin-top:9px" ${u.googleLinked?'disabled':''}>${u.googleLinked?'Google bağlı':'Google hesabını bağla…'}</button>`;document.querySelector('.entry-modal .form-footer').before(googlePanel);googlePanel.querySelector('#google-link').onclick=async()=>{try{db.user=await window.rafDesktop.googleLogin({clientId:googlePanel.querySelector('#google-client-id').value.trim()});closeModal();toast('Google hesabı yerel profile bağlandı.')}catch(e){toast(e.message||'Google hesabı bağlanamadı.')}};
   document.querySelector('#export-btn').onclick=async()=>{try{if(await window.rafDesktop.exportLibrary())toast('Şifrelenmemiş yedek dosyası seçtiğin yere kaydedildi.')}catch(e){toast(e.message)}};
   document.querySelector('#import-btn').onclick=async()=>{try{let data=await window.rafDesktop.importLibrary();if(data){db.items=normalizeItems(data);save();render();closeModal();toast('Yedek içe aktarıldı.')}}catch(e){toast(e.message)}};
   document.querySelector('#logout-btn').onclick=async()=>{await window.rafDesktop.logout();db.user=null;db.items=[];closeModal();render();desktopAccount(true)};
   document.querySelector('#clear-btn').onclick=()=>{if(confirm(tx('Arşivindeki bütün kayıtları kalıcı olarak silmek istiyor musun?'))){db.items=[];save();closeModal();render();toast('Arşiv temizlendi.')}};
 }else{
   document.querySelector('#modal-root').innerHTML=top+`<div class="filter-row"><button class="filter-chip active" data-tab="login">Giriş yap</button><button class="filter-chip" data-tab="register">Yerel hesap oluştur</button></div><form id="auth-form"><div class="form-grid"><div class="field full" id="name-field" style="display:none"><label>ADIN (İSTEĞE BAĞLI)</label><input name="name" maxlength="80" placeholder="Ada"/></div><div class="field full"><label>E-POSTA</label><input type="email" name="email" required autocomplete="username" placeholder="sen@ornek.com"/></div><div class="field full"><label>PAROLA</label><input type="password" name="password" required minlength="1" autocomplete="current-password" placeholder="Yerel hesap parolan"/></div></div><p class="form-note" style="margin:13px 0">Bu e-posta yalnızca cihazındaki yerel hesabı adlandırmak için kullanılır; doğrulama e-postası gönderilmez. Parola scrypt ile doğrulanır ve arşiv AES-GCM ile şifrelenir. Parolan unutulursa kurtarma yoktur.</p><button class="primary-btn" id="auth-submit">Giriş yap</button><span id="auth-error" class="form-note" style="color:#e1a69e;margin-left:10px"></span></form>`+footer;
   let tab='login';document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;document.querySelectorAll('[data-tab]').forEach(x=>x.classList.toggle('active',x===b));document.querySelector('#name-field').style.display=tab==='register'?'grid':'none';document.querySelector('[name="password"]').autocomplete=tab==='register'?'new-password':'current-password';document.querySelector('#auth-submit').textContent=tab==='register'?'Hesap oluştur':'Giriş yap'});
   document.querySelector('#auth-form').onsubmit=async e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.target));try{db.user=tab==='register'?await window.rafDesktop.register(d):await window.rafDesktop.login(d);db.items=await window.rafDesktop.readLibrary();desktopLocked=false;closeModal();document.querySelector('#avatar-button').textContent=(db.user.name||db.user.email)[0].toUpperCase();render();toast(tab==='register'?'Yerel hesap oluşturuldu.':'Hoş geldin.')}catch(err){document.querySelector('#auth-error').textContent=tx(err.message)||'İşlem başarısız.'}};
   const googlePanel=document.createElement('div');googlePanel.className='account-card';googlePanel.innerHTML=`<b>Google ile oturum aç · isteğe bağlı</b><br>Google hesabın bu cihazdaki yerel Raf hesabına bağlanır. Eşitleme yapılmaz.<div class="field" style="margin-top:11px"><label>GOOGLE DESKTOP CLIENT ID</label><input id="google-client-id" placeholder="....apps.googleusercontent.com"/></div><div class="field" style="margin-top:9px"><label>YEREL KASA PAROLASI · YENİ HESAPTA ZORUNLU</label><input id="google-vault-password" type="password" minlength="12" placeholder="En az 12 karakter"/></div><p class="form-note" style="margin-top:9px">Google e-posta ve profil adını doğrular. Arşiv bu cihazda şifreli kalır. İlk girişte belirlediğin yerel parolayla daha sonra çevrimdışı da açabilirsin.</p><button id="google-signin" class="secondary-btn" style="margin-top:9px">Google ile devam et…</button>`;document.querySelector('#auth-form').after(googlePanel);
   googlePanel.querySelector('#google-signin').onclick=async()=>{try{const clientId=googlePanel.querySelector('#google-client-id').value.trim(),password=googlePanel.querySelector('#google-vault-password').value;db.user=await window.rafDesktop.googleLogin({clientId,password});db.items=await window.rafDesktop.readLibrary();desktopLocked=false;closeModal();document.querySelector('#avatar-button').textContent=(db.user.name||db.user.email)[0].toUpperCase();render();toast('Google hesabın bu cihazda açıldı.')}catch(err){document.querySelector('#auth-error').textContent=tx(err.message)||'Google oturumu açılamadı.'}};
 }
 document.querySelectorAll('[data-close]').forEach(b=>b.onclick=closeModal);document.querySelectorAll('[data-legal]').forEach(b=>b.onclick=()=>openLegal(b.dataset.legal));
}
function account(){if(desktop){desktopAccount();return}const u=db.users.find(x=>x.id===db.user);document.querySelector('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="entry-modal" style="max-width:440px"><div class="modal-head"><div><span class="eyebrow">HESAP & VERİ</span><h2 style="margin-top:8px">${u?'Senin Rafın':'Yerel hesap'}</h2></div><button class="close-btn" data-close>×</button></div>${u?`<div class="account-card"><b>${esc(u.name||'Kullanıcı')}</b><br>${esc(u.email)}<br><span style="color:#82b38d">● Bu tarayıcıda oturum açık</span></div><div style="display:flex;gap:8px;flex-wrap:wrap"><button class="secondary-btn" id="export-btn">Yedek indir (JSON)</button><button class="secondary-btn" id="import-btn">Yedek yükle</button><button class="secondary-btn" id="logout-btn">Oturumu kapat</button><button class="danger-btn" id="clear-btn">Arşivi temizle</button></div>`:`<p class="page-intro">Bu prototipte hesap bilgileri sadece bu tarayıcıda saklanır; e-posta doğrulaması veya gerçek parola güvenliği yoktur.</p><div class="filter-row"><button class="filter-chip active" data-tab="login">Giriş yap</button><button class="filter-chip" data-tab="register">Hesap oluştur</button></div><form id="auth-form"><div class="form-grid"><div class="field full" id="name-field" style="display:none"><label>ADIN</label><input name="name" placeholder="Ada"/></div><div class="field full"><label>E-POSTA</label><input type="email" name="email" required placeholder="sen@ornek.com"/></div><div class="field full"><label>PAROLA</label><input type="password" name="password" required minlength="4" placeholder="En az 4 karakter"/></div></div><p class="form-note" style="margin:13px 0">Yerel demo hesap: parola güvenli saklanmaz ve kurtarılamaz. Gerçek kullanıcılarla yayımlamadan önce güvenli kimlik doğrulama servisi bağlanmalıdır.</p><button class="primary-btn" id="auth-submit">Giriş yap</button></form>`}<div class="form-footer"><span class="form-note">Verilerin cihazında kalır.</span><button class="text-btn" data-legal="privacy">Gizlilik</button></div></section></div>`;document.querySelectorAll('[data-close]').forEach(b=>b.onclick=closeModal);document.querySelectorAll('[data-legal]').forEach(b=>b.onclick=()=>openLegal(b.dataset.legal));if(!u){let tab='login';document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;document.querySelectorAll('[data-tab]').forEach(x=>x.classList.toggle('active',x===b));document.querySelector('#name-field').style.display=tab==='register'?'grid':'none';document.querySelector('#auth-submit').textContent=tab==='register'?'Hesap oluştur':'Giriş yap'});document.querySelector('#auth-form').onsubmit=e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.target)),email=d.email.toLowerCase().trim();if(tab==='register'){if(db.users.some(x=>x.email===email)){toast('Bu e-posta ile hesap zaten var.');return}let u={id:crypto.randomUUID(),email,password:d.password,name:d.name};db.users.push(u);db.user=u.id;save();closeModal();document.querySelector('#avatar-button').textContent=(u.name||u.email)[0].toUpperCase();toast('Yerel hesabın oluşturuldu.')}else{let u=db.users.find(x=>x.email===email&&x.password===d.password);if(!u){toast('E-posta veya parola eşleşmedi.');return}db.user=u.id;save();closeModal();document.querySelector('#avatar-button').textContent=(u.name||u.email)[0].toUpperCase();toast('Hoş geldin.')}}}else{document.querySelector('#export-btn').onclick=()=>{let blob=new Blob([JSON.stringify(db,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='raf-yedek.json';a.click();URL.revokeObjectURL(a.href)};document.querySelector('#import-btn').onclick=()=>{let f=document.createElement('input');f.type='file';f.accept='.json,application/json';f.onchange=()=>{let reader=new FileReader();reader.onload=()=>{try{let j=JSON.parse(reader.result);if(!Array.isArray(j.items))throw 0;db.items=j.items;save();closeModal();render();toast('Yedek yüklendi.')}catch{toast('Bu dosya geçerli bir RAF yedeği değil.')}};reader.readAsText(f.files[0])};f.click()};document.querySelector('#logout-btn').onclick=()=>{db.user=null;save();closeModal();toast('Oturum kapatıldı.')};document.querySelector('#clear-btn').onclick=()=>{if(confirm(tx('Arşivindeki bütün kayıtları silmek istiyor musun?'))){db.items=[];save();closeModal();render();toast('Arşiv temizlendi.')}}}}
document.querySelector('#menu-toggle').onclick=()=>document.querySelector('#sidebar').classList.toggle('collapsed');document.querySelector('#account-button').onclick=account;document.querySelector('#avatar-button').onclick=account;document.querySelector('#search-input').oninput=e=>{query=e.target.value;view='all';render()};document.querySelector('#language-select').onchange=e=>{currentLang=e.target.value;document.documentElement.lang=currentLang;render()};new MutationObserver(()=>localize(document.querySelector('#modal-root'))).observe(document.querySelector('#modal-root'),{childList:true,subtree:true});document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();document.querySelector('#search-input').focus()}if(e.key==='Escape'&&!desktopLocked)closeModal()});
async function boot(){if(desktop){try{db.user=await window.rafDesktop.session();if(db.user){db.items=await window.rafDesktop.readLibrary();document.querySelector('#avatar-button').textContent=(db.user.name||db.user.email)[0].toUpperCase();render()}else{db.items=[];render();desktopAccount(true)}}catch(e){db.user=null;db.items=[];render();desktopAccount(true);toast(e.message||'Arşiv açılamadı.')}}else render()}
boot();
